import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),site=path.join(root,'site');
const read=name=>fs.readFile(path.join(site,name),'utf8');
const logo='data:image/jpeg;base64,'+(await fs.readFile(path.join(site,'assets/secheron.jpg'))).toString('base64');
const modules=['model.js','pdf.js','xlsx.js','assets.js','offline.js','numbering-config.js','numbering.js','app.js'];
const scripts=[];for(const name of modules)scripts.push((await read(name)).replace(/^import .*;\s*$/gm,'').replace(/^export /gm,''));
const vendor=(await read('vendor/pdf-lib.min.js')).replace(/\/\/# sourceMappingURL=.*$/gm,'');
const escapeScript=text=>text.replace(/<\/script/gi,'<\\/script');
let html=await read('index.html');
html=html.replace(/\s*<link rel="manifest"[^>]*>/g,'').replace(/\s*<link rel="apple-touch-icon"[^>]*>/g,'');
html=html.replace('<link rel="stylesheet" href="styles.css">',`<style>${await read('styles.css')}</style>`);
html=html.replace(/\s*<script\b[^>]*src="[^"]+"[^>]*><\/script>/g,'');
html=html.replace('</body>',`<script>globalThis.SECHERON_PORTABLE_ASSETS=${JSON.stringify({logo})};</script>\n<script>${escapeScript(vendor)}</script>\n<script>(function(){'use strict';\n${escapeScript(scripts.join('\n'))}\n})();</script>\n</body>`);
await fs.writeFile(path.join(root,'Abrir_Gerador_Offline.html'),html);
const assets=['./','./index.html','./styles.css','./app.js','./model.js','./pdf.js','./xlsx.js','./assets.js','./offline.js','./numbering-config.js','./numbering.js','./vendor/pdf-lib.min.js','./assets/secheron.jpg','./manifest.webmanifest','./assets/icon-192.png','./assets/icon-512.png'];
const hash=crypto.createHash('sha256');for(const name of assets.filter(n=>n!=='./'))hash.update(await fs.readFile(path.join(site,name)));
const version=hash.digest('hex').slice(0,16);
const worker=`// Generated by scripts/build-portable.mjs. Code assets only; no reports are cached here.
const PREFIX='secheron-reports-'+encodeURIComponent(new URL(self.registration.scope).pathname)+'-';
const CACHE=PREFIX+'${version}';
const ASSETS=${JSON.stringify(assets)};
const rootURL=new URL('./',self.registration.scope).href;
self.addEventListener('install',event=>event.waitUntil((async()=>{
 try{const cache=await caches.open(CACHE);await cache.addAll(ASSETS.map(p=>new Request(new URL(p,rootURL).href,{cache:'reload'})));}
 catch(error){await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys()){if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);}await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==new URL(rootURL).origin||!url.pathname.startsWith(new URL(rootURL).pathname))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);if(event.request.mode==='navigate'){const page=await cache.match(new URL('./index.html',rootURL).href);if(page)return page;}
 const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;return fetch(event.request);})());
});
`;
await fs.writeFile(path.join(site,'sw.js'),worker);
console.log(`Portable HTML and PWA prepared. Cache version ${version}.`);
